def ref(path, needle, after=8, before=0, version='head', label=None):
    return dict(path=path, needle=needle, after=after, before=before, version=version, label=label)


def old(path, needle, after=8, before=0):
    return ref(path, needle, after, before, 'base')


def reason(needle, after=0):
    return ref(RECORD, needle, after, label='Inherited policy record')


def pr(needle):
    return ref('pr-body.md', needle, 0, version='bundle', label='PR body · Decisions')


